#include <iostream>
using namespace std;
int x,y,r,j,l,h,q,z,i,o,n,m,d,f,k,t,u;
char*s,*c,*v,b;
int main(){cout<<"ROBOTRON\n";cout<<"X:";cin>>x;cout<<"Y:";cin>>y;cout<<"R:";cin>>r;cout<<"J:";cin>>j;if((x*y)<(r+j+1)){cout<<"SCREEN TOO SMALL!"<<endl;return 1;}cout<<"L:";cin>>l;cout<<"H:";cin>>h;q=x/2;z=y/2;s=new char[x*y];c=new char[x*y];memset(s,' ',x*y);s[q+(z*x)]='@';for(;i<r;i++){n=rand()%x;m=rand()%y;(s[n+(m*x)]==' ')?s[n+(m*x)]='#':i--;}for(i=0;i<j;i++){n=rand()%x;m=rand()%y;(s[n+(m*x)]==' ')?s[n+(m*x)]='^':i--;}while(l>0&&r>0){system("cls");for(i=0;i<y;i++){for(o=0;o<x;o++){cout<<s[o+(i*x)];}cout<<endl;}cout<<"Lives: "<<l<<" Robots: "<<r<<" Hyperspace: "<<h<<endl;memset(c,' ',x*y);b;cin>>b;n=q,m=z;switch(b){case'w':m--;break;case's':m++;break;case'a':n--;break;case'd':n++;break;case'h':if(!h)continue;while(s[n+(m*x)]!=' '&&h>0)n=rand()%x,m=rand()%y;;h--;break;default:continue;}if(n<0||n>=x||m<0||m>=y)continue;s[q+(z*x)]=' ';(s[n+(m*x)]=='#')?l--,s[n+(m*x)]='@',c[n+(m*x)]='@',q=n,z=m:s[n+(m*x)]='@',c[n+(m*x)]='@',q=n,z=m;for(i=0;i<y;i++){for(o=0;o<x;o++){k=o+(i*x);if(s[k]=='#'){t=0, u=0;if(o>q)t=-1;else if(o<q)t=1;if(i>z)u=-1;else if(i<z)u=1;d=o+t;f=i+u;s[o+(i*x)]=' ';if(c[d+(f*x)]=='@')l--;else if(s[d+(f*x)]=='^'||c[d+(f*x)]=='#')c[d+(f*x)]='^';else c[d+(f*x)]='#';}else if(s[k]=='^')c[k]=s[k];}}r=0;for(;i<x*y;i++){if(c[i]=='#')r++;}v=s;s=c;c=v;}if(!r){cout<<"You win!"<<endl;}else if(!l){cout<<"You lose!"<<endl;}cout<<"Game Over!"<<endl;delete[] s;delete[] c;}
